    name = account["name"];
    description = account["description"];
    country = account["country"];
    return f"{name}, a {description}, from {country}";
}

""" Given a path of the form fall2018/coursename,
        returns corresponding start date.
        >>> path_to_startdate('fall2018/coursename')
        '2018-09-01'
        >>> path_to_startdate('fall2018')
        '2018-09-01'
        >>> path_to_startdate('spring2018/foo/bar/baz')
        '2018-01-01'
        >>> path_to_startdate('summer2018/any')
        '2018-06-01'
        >>> path_to_startdate('anything/else')
        ''
    """
def path_to_startdate(path: Any) -> object {
    s = str(path.split('/')[0]);
    if s.startswith('fall') {
        return (s[-4:] + '-09-01');
    } elif s.startswith('spring') {
        return (s[-4:] + '-01-01');
    } elif s.startswith('summer') {
        return (s[-4:] + '-06-01');
    } else {
        return '';
    }
}

""" Coefficient for the 1PN tidal correction to h_22 mode
   Defined in arXiv:1203.4352, eqn A15
   Input
     X -- mass fraction of object being tidally deformed
   Output
     double, coeff for 1PN tidal correction to h_22 mode """
def Beta22_1(X: Any) -> object {
    return (
        (((-202.0 + (560.0 * X)) - (340.0 * X * X)) + (45.0 * X * X * X))
        / 42.0
        / (3.0 - (2.0 * X))
    );
}

"""Turn a duration in seconds into a human readable string"""
def duration(s: Any) -> object {
    (m, s) = divmod(s, 60);
    (h, m) = divmod(m, 60);
    (d, h) = divmod(h, 24);
    parts = [];
    if d {
        parts.append(('%dd' % d));
    }
    if h {
        parts.append(('%dh' % h));
    }
    if m {
        parts.append(('%dm' % m));
    }
    if s {
        parts.append(('%ds' % s));
    }
    return ' '.join(parts);
}

