def duration(s):
    """Turn a duration in seconds into a human readable string"""
    m, s = divmod(s, 60)
    h, m = divmod(m, 60)
    d, h = divmod(h, 24)

    parts = []
    if d:
        parts.append('%dd' % d)
    if h:
        parts.append('%dh' % h)
    if m:
        parts.append('%dm' % m)
    if s:
        parts.append('%ds' % s)

    return ' '.join(parts)

