"""Shake-shake regularization in testing mode.

  Args:
    xa: Input, branch A.
    xb: Input, branch B.

  Returns:
    Mix of input branches.
  """
def shake_shake_eval(xa: Any, xb: Any) -> object {
    return ((xa + xb) * 0.5);
}

"""
    Pack byte to network order unsigned short
    """
def pack_byte_to_hn(val: Any) -> object {
    return ((val << 8) & 65535);
}
